def parse_csv_line(line):
    if not line:
        return [""]

    fields = []
    current_field = []
    in_quotes = False
    escape_next = False

    for char in line:
        if escape_next:
            current_field.append(char)
            escape_next = False
            continue

        if char == '"':
            if in_quotes:
                if len(current_field) > 0 and current_field[-1] == '"':
                    current_field.pop()  # Remove the previous quote
                else:
                    escape_next = True
            else:
                in_quotes = True
        elif char == ',':
            if in_quotes:
                current_field.append(char)
            else:
                fields.append(''.join(current_field))
                current_field = []
        else:
            current_field.append(char)

    if in_quotes:
        raise ValueError("Unclosed quote")

    fields.append(''.join(current_field))

    # Handle trailing comma
    if line.endswith(','):
        fields.append('')

    return fields

