from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key):
        if key not in self.cache:
            return None
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key, value):
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

    def __len__(self):
        return len(self.cache)

    def keys(self):
        return list(self.cache.keys())

def flatten_dict(d, sep="."):
    """Flatten a nested dictionary into a single-level dictionary.

    Args:
        d: The dictionary to flatten.
        sep: The separator to use between keys in nested paths.

    Returns:
        A new flattened dictionary.
    """
    flattened = {}

    def _flatten(current_dict, current_key):
        for key, value in current_dict.items():
            new_key = f"{current_key}{sep}{key}" if current_key else key
            if isinstance(value, dict):
                _flatten(value, new_key)
            else:
                flattened[new_key] = value

    _flatten(d, "")
    return flattened

def median(values):
    if not values:
        raise ValueError("median() arg is an empty sequence")
    s = sorted(values)
    n = len(s)
    if n % 2 == 1:
        return s[n // 2]
    else:
        return (s[n // 2 - 1] + s[n // 2]) / 2

def chunked(items, size):
    if size < 1:
        raise ValueError("Size must be at least 1")
    return [list(items[i:i + size]) for i in range(0, len(items), size)]

def append_unique(item, bucket=None):
    if bucket is None:
        bucket = []
    if item not in bucket:
        bucket.append(item)
    return bucket

