from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity, ttl, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        if ttl <= 0:
            raise ValueError("TTL must be greater than 0")
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache = OrderedDict()

    def put(self, key, value):
        current_time = self.clock()
        # Remove expired entries first
        self._remove_expired()
        # If key exists, remove it to update its position and expiry
        if key in self.cache:
            del self.cache[key]
        # Add new entry with expiry time
        self.cache[key] = (value, current_time + self.ttl)
        # Move to end to mark as most recently used
        self.cache.move_to_end(key)
        # Evict if over capacity
        while len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

    def get(self, key):
        current_time = self.clock()
        # Remove expired entries first
        self._remove_expired()
        if key not in self.cache:
            return None
        # Move to end to mark as most recently used
        self.cache.move_to_end(key)
        return self.cache[key][0]

    def __len__(self):
        self._remove_expired()
        return len(self.cache)

    def keys(self):
        self._remove_expired()
        return list(self.cache.keys())

    def _remove_expired(self):
        current_time = self.clock()
        # Iterate over a copy of keys to avoid modification during iteration
        keys_to_remove = [k for k, (v, expiry) in self.cache.items() if current_time >= expiry]
        for k in keys_to_remove:
            del self.cache[k]

