import heapq
from collections import defaultdict

def shortest_path(graph, src, dst):
    # Check if src or dst is not in the graph
    if src not in graph and src not in {neighbor for neighbors in graph.values() for neighbor in neighbors}:
        raise ValueError(f"Source node {src} not found in the graph")
    if dst not in graph and dst not in {neighbor for neighbors in graph.values() for neighbor in neighbors}:
        raise ValueError(f"Destination node {dst} not found in the graph")

    # Check for zero or negative weights
    for neighbors in graph.values():
        for neighbor, weight in neighbors.items():
            if weight <= 0:
                raise ValueError("Weight must be greater than zero")

    # Handle case where src == dst
    if src == dst:
        return (0, [src])

    # Build adjacency list and reverse adjacency list for path reconstruction
    adj = defaultdict(dict)
    for node in graph:
        for neighbor, weight in graph[node].items():
            adj[node][neighbor] = weight

    # Priority queue: (distance, current_node)
    heap = []
    heapq.heappush(heap, (0, src))

    # Track visited nodes and their distances
    visited = {}
    predecessors = {}

    while heap:
        current_dist, current_node = heapq.heappop(heap)

        if current_node == dst:
            # Reconstruct the path
            path = []
            while current_node in predecessors:
                path.append(current_node)
                current_node = predecessors[current_node]
            path.append(src)
            path.reverse()
            return (current_dist, path)

        if current_node in visited:
            continue
        visited[current_node] = current_dist

        for neighbor, weight in adj.get(current_node, {}).items():
            if neighbor not in visited:
                new_dist = current_dist + weight
                heapq.heappush(heap, (new_dist, neighbor))
                if neighbor not in predecessors or new_dist < visited.get(neighbor, float('inf')):
                    predecessors[neighbor] = current_node

    # If dst is not reachable
    return None

import heapq
from collections import defaultdict

def shortest_path(graph, src, dst):
    # Check if src or dst is not in the graph
    nodes = set(graph.keys()).union({neighbor for neighbors in graph.values() for neighbor in neighbors})
    if src not in nodes:
        raise ValueError(f"Source node {src} not found in the graph")
    if dst not in nodes:
        raise ValueError(f"Destination node {dst} not found in the graph")

    # Check for zero or negative weights
    for neighbors in graph.values():
        for weight in neighbors.values():
            if weight <= 0:
                raise ValueError("Weight must be greater than zero")

    # Handle case where src == dst
    if src == dst:
        return (0, [src])

    # Build adjacency list
    adj = defaultdict(dict)
    for node in graph:
        for neighbor, weight in graph[node].items():
            adj[node][neighbor] = weight

    # Priority queue: (distance, current_node, path)
    heap = []
    heapq.heappush(heap, (0, src, [src]))

    # Track visited nodes and their shortest distances
    visited = {}

    while heap:
        current_dist, current_node, path = heapq.heappop(heap)

        if current_node == dst:
            return (current_dist, path)

        if current_node in visited and visited[current_node] <= current_dist:
            continue
        visited[current_node] = current_dist

        for neighbor, weight in adj.get(current_node, {}).items():
            new_dist = current_dist + weight
            new_path = path + [neighbor]
            heapq.heappush(heap, (new_dist, neighbor, new_path))

    # If dst is not reachable
    return None

class OutOfStock(Exception):
    pass

class Inventory:
    def __init__(self, stock=None):
        self._stock = stock.copy() if stock is not None else {}

    def stock(self, item):
        return self._stock.get(item, 0)

    def add(self, item, qty):
        if qty <= 0:
            raise ValueError("Quantity must be positive")
        self._stock[item] = self.stock(item) + qty

    def remove(self, item, qty):
        if qty <= 0:
            raise ValueError("Quantity must be positive")
        if self.stock(item) < qty:
            raise OutOfStock(f"Not enough stock for {item}")
        self._stock[item] = self.stock(item) - qty

def fulfil(inventory, order):
    if not isinstance(order, dict):
        raise ValueError("Order must be a dictionary")

    # Check all quantities are positive before modifying inventory
    for qty in order.values():
        if qty <= 0:
            raise ValueError("Order quantities must be positive")

    temp_stock = inventory._stock.copy()
    total = 0
    try:
        for item, qty in order.items():
            if temp_stock[item] < qty:
                raise OutOfStock(f"Not enough stock for {item}")
            temp_stock[item] -= qty
            total += qty
        # Only update inventory if all items are available
        inventory._stock = temp_stock
    except OutOfStock:
        # Revert inventory if any item is out of stock
        inventory._stock = temp_stock.copy()
        raise
    return total

