import re
from collections import defaultdict

def render(template, context):
    stack = []
    output = []
    i = 0
    n = len(template)

    def add(text):
        nonlocal i
        output.append(text)
        i += len(text)

    def parse_path(path):
        parts = re.split(r'\.|\[|\]', path)
        current = context
        for part in parts:
            if not part:
                continue
            if isinstance(current, dict) and part in current:
                current = current[part]
            elif isinstance(current, list) and part.isdigit():
                idx = int(part)
                if 0 <= idx < len(current):
                    current = current[idx]
                else:
                    return None
            else:
                return None
        return current

    def apply_filter(value, filter_name):
        if value is None:
            value = ""
        if filter_name == "upper":
            return str(value).upper()
        elif filter_name == "lower":
            return str(value).lower()
        elif filter_name == "title":
            return str(value).title()
        elif filter_name == "length":
            return str(len(value))
        else:
            raise ValueError(f"Unknown filter: {filter_name}")

    def parse_tag():
        nonlocal i
        tag_start = i
        while i < n and template[i] != '}':
            i += 1
        tag_content = template[tag_start + 2:i]
        tag_content = tag_content.strip()
        if not tag_content:
            return None, None

        if tag_content.startswith('if '):
            condition = tag_content[3:].strip()
            is_not = condition.startswith('not ')
            if is_not:
                condition = condition[4:].strip()
            path = condition.split()[0]
            return 'if', (is_not, path)
        elif tag_content.startswith('else'):
            return 'else', None
        elif tag_content.startswith('endif'):
            return 'endif', None
        elif tag_content.startswith('for '):
            parts = tag_content[4:].strip().split(' in ')
            if len(parts) != 2:
                raise ValueError("Invalid for tag")
            name, path = parts
            return 'for', (name, path)
        elif tag_content.startswith('endfor'):
            return 'endfor', None
        else:
            if '|' in tag_content:
                path, filter_name = tag_content.split('|', 1)
                path = path.strip()
                filter_name = filter_name.strip()
                return 'filter', (path, filter_name)
            else:
                return 'value', tag_content

    while i < n:
        if template[i] == '{' and i + 1 < n and template[i+1] == '{':
            i += 2
            tag_type, tag_data = parse_tag()
            if tag_type is None:
                add('{{')
                continue
            if i >= n or template[i] != '}':
                raise ValueError("Unclosed tag")

            if tag_type == 'value':
                path = tag_data
                value = parse_path(path)
                if value is None:
                    add("")
                else:
                    add(str(value))
            elif tag_type == 'filter':
                path, filter_name = tag_data
                value = parse_path(path)
                try:
                    filtered_value = apply_filter(value, filter_name)
                    add(filtered_value)
                except ValueError:
                    raise
            elif tag_type == 'if':
                is_not, path = tag_data
                value = parse_path(path)
                if (not is_not and value) or (is_not and not value):
                    stack.append(tag_type)
                else:
                    if stack and stack[-1] == 'if':
                        stack.pop()
                    else:
                        raise ValueError("Unmatched if tag")
            elif tag_type == 'else':
                if stack and stack[-1] == 'if':
                    stack.pop()
                    stack.append('else')
                else:
                    raise ValueError("Unmatched else tag")
            elif tag_type == 'endif':
                if stack and stack[-1] == 'if':
                    stack.pop()
                elif stack and stack[-1] == 'else':
                    stack.pop()
                else:
                    raise ValueError("Unmatched endif tag")
            elif tag_type == 'for':
                name, path = tag_data
                value = parse_path(path)
                if value is None or not isinstance(value, list):
                    i += 1
                    continue
                stack.append(('for', name, path))
                for item in value:
                    context[name] = item
                    add(render(template[i+1:], context))
                    i += 1
                    break
            elif tag_type == 'endfor':
                if stack and stack[-1][0] == 'for':
                    stack.pop()
                else:
                    raise ValueError("Unmatched endfor tag")
            i += 1
        else:
            add(template[i])
            i += 1

    if stack:
        raise ValueError("Unclosed tag")

    return ''.join(output)

