        tag_content = template[tag_start + 2:i]
        tag_content = tag_content.strip()

        if not tag_content:
            return None, None

        if tag_content.startswith('if '):
            condition = tag_content[3:].strip()
            is_not = condition.startswith('not ')
            if is_not:
                condition = condition[4:].strip()
            path = condition.split()[0]
            return 'if', (is_not, path)
        elif tag_content.startswith('else'):
            return 'else', None
        elif tag_content.startswith('endif'):
            return 'endif', None
        elif tag_content.startswith('for '):
            parts = tag_content[4:].strip().split(' in ')
            if len(parts) != 2:
                raise ValueError("Invalid for tag")
            name, path = parts
            return 'for', (name, path)
        elif tag_content.startswith('endfor'):
            return 'endfor', None
        else:
            if '|' in tag_content:
                path, filter_name = tag_content.split('|', 1)
                path = path.strip()
                filter_name = filter_name.strip()
                return 'filter', (path, filter_name)
            else:
                return 'value', tag_content

    while i < n:
        if template[i] == '{' and i + 1 < n and template[i+1] == '{':
            i += 2
            tag_type, tag_data = parse_tag()
            if tag_type is None:
                add('{{')
                continue
            if i >= n or template[i] != '}':
                raise ValueError("Unclosed tag")

            if tag_type == 'value':
                path = tag_data
                value = parse_path(path)
                if value is None:
                    add("")
                else:
                    add(str(value))
            elif tag_type == 'filter':
                path, filter_name = tag_data
                value = parse_path(path)
                try:
                    filtered_value = apply_filter(value, filter_name)
                    add(filtered_value)
                except ValueError:
                    raise
            elif tag_type == 'if':
                is_not, path = tag_data
                value = parse_path(path)
                if (not is_not and value) or (is_not and not value):
                    # Find the matching endif
                    depth = 1
                    j = i + 1
                    while j < n and depth > 0:
                        if template[j] == '{' and j + 1 < n and template[j+1] == '%':
                            j += 2
                            if template[j:j+6] == 'endif':
                                depth -= 1
                                j += 6
                            elif template[j:j+4] == 'else':
                                depth += 1
                                j += 4
                            else:
                                j += 1
                        else:
                            j += 1
                    if depth != 0:
                        raise ValueError("Unmatched if tag")
                    # Render the content between if and endif
                    content = template[i+1:j]
                    add(render(content, context))
                    i = j
                else:
                    # Check for else
                    if template[i+1:].startswith('{% else %}'):
                        j = i + 8
                        # Find the matching endif
                        depth = 1
                        while j < n and depth > 0:
                            if template[j] == '{' and j + 1 < n and template[j+1] == '%':
                                j += 2
                                if template[j:j+6] == 'endif':
                                    depth -= 1
                                    j += 6
                                elif template[j:j+4] == 'else':
                                    depth += 1
                                    j += 4
                                else:
                                    j += 1
                            else:
                                j += 1
                        if depth != 0:
                            raise ValueError("Unmatched else tag")
                        content = template[i+8:j]
                        add(render(content, context))
                        i = j
                    else:
                        i += 1
            elif template[i+1:].startswith('{% else %}'):
                i += 8
                # Find the matching endif
                depth = 1
                j = i
                while j < n and depth > 0:
                    if template[j] == '{' and j + 1 < n and template[j+1] == '%':
                        j += 2
                        if template[j:j+6] == 'endif':
                            depth -= 1
                            j += 6
                        elif template[j:j+4] == 'else':
                            depth += 1
                            j += 4
                        else:
                            j += 1
                    else:
                        j += 1
                if depth != 0:
                    raise ValueError("Unmatched else tag")
                content = template[i:j]
                add(render(content, context))
                i = j
            elif tag_type == 'for':
                name, path = tag_data
                value = parse_path(path)
                if value is None or not isinstance(value, list):
                    i += 1
                    continue
                # Find the matching endfor
                depth = 1
                j = i + 1
                while j < n and depth > 0:
                    if template[j] == '{' and j + 1 < n and template[j+1] == '%':
                        j += 2
                        if template[j:j+6] == 'endfor':
                            depth -= 1
                            j += 6
                        elif template[j:j+4] == 'for ':
                            depth += 1
                            j += 4
                        else:
                            j += 1
                    else:
                        j += 1
                if depth != 0:
                    raise ValueError("Unmatched endfor tag")
                content = template[i+1:j]
                for item in value:
                    context[name] = item
                    add(render(content, context))
                i = j
            i += 1
        else:
            add(template[i])
            i += 1

    return ''.join(output)
